/** Convert "#RRGGBB" (or "" -> fallback) to FLinearColor in sRGB-to-linear space. */
inline FLinearColor LihlHexToColor(const FString& Hex, const FLinearColor& Fallback = FLinearColor::White)
{
	if (Hex.IsEmpty()) { return Fallback; }
	return FLinearColor::FromSRGBColor(FColor::FromHex(Hex)); // TODO(verify on compile): FColor::FromHex signature
}
